    var ChartManager = {
      charts: new Map(),
      safeInit: function(canvasId, config) {
        if (typeof Chart === 'undefined') {
          console.error('Chart.js not loaded');
          return null;
        }
        try {
          if (this.charts.has(canvasId)) {
            this.charts.get(canvasId).destroy();
            this.charts.delete(canvasId);
          }
          var ctx = document.getElementById(canvasId);
          if (!ctx) return null;
          var chart = new Chart(ctx, config);
          this.charts.set(canvasId, chart);
          return chart;
        } catch (e) {
          console.error('Chart init failed', e);
          return null;
        }
      }
    };

    function commonScales() {
      return {
        x: {
          ticks: { color: getComputedStyle(document.body).getPropertyValue('--text-secondary') },
          grid: { color: 'rgba(158,177,216,0.18)' }
        },
        y: {
          ticks: { color: getComputedStyle(document.body).getPropertyValue('--text-secondary') },
          grid: { color: 'rgba(158,177,216,0.18)' }
        }
      };
    }

    function renderCharts() {
      if (typeof Chart === 'undefined') { console.error('Chart.js not loaded'); return; }
      var text = getComputedStyle(document.body).getPropertyValue('--text');
      var accent = getComputedStyle(document.body).getPropertyValue('--accent');
      var accent2 = getComputedStyle(document.body).getPropertyValue('--accent-secondary');
      var warn = getComputedStyle(document.body).getPropertyValue('--warning');

      ChartManager.safeInit('langChart', {
        type: 'bar',
        data: {
          labels: ['Python','TypeScript','Rust','Verilog','HTML','JavaScript','Dart','Shell'],
          datasets: [{
            label: 'Repo count',
            data: [7,5,2,1,1,1,1,1],
            backgroundColor: [accent,accent,'#829fff',warn,warn,warn,warn,warn],
            borderRadius: 6
          }]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          plugins: { legend: { display:false, labels:{color:text} }, tooltip: { enabled: true } },
          scales: commonScales()
        }
      });

      ChartManager.safeInit('categoryChart', {
        type: 'doughnut',
        data: {
          labels: ['AI/Agent related (14)','Other (6)'],
          datasets: [{
            data: [14,6],
            backgroundColor: [accent2, '#3a4a72'],
            borderColor: '#0b1020',
            borderWidth: 2
          }]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          plugins: { legend: { labels: { color: text } }, tooltip: { enabled: true } }
        }
      });
    }

    function toggleTheme() {
      document.body.classList.toggle('theme-light');
      document.body.classList.toggle('theme-dark');
      renderCharts();
    }

